    [LVRULE_RANGELVTYPEFLAG] CHAR(1) NULL  -- For Working days computation - Leaves to be considered,
    [LVRULE_CONVERTFLAG] CHAR(1) NOT NULL  -- Convert leave balance  (Y)es or (N)o,
    [LVRULE_CONVERTLEAVEID] INT NULL  -- Convert leave type as,
