    [LVRULE_MINDAYSINAPPL] INT NOT NULL  -- Minimum no of days allowed in a single leave application,
    [LVRULE_APPNOS] INT NOT NULL  -- No of leave applications allowed in a Calendar Year,
    [LVRULE_NPHINC] CHAR(1) NOT NULL  -- NPH to be considered (Y/N),
    [LVRULE_WEEKOFFINC] CHAR(1) NOT NULL  -- Weekly off to be considered (Y/N),
    [LVRULE_WEEKOFFRESTRICT] CHAR(1) NOT NULL  -- Leave application cannot precede or succeed weekly off,
    [LVRULE_ALLOWBKD] CHAR(1) NOT NULL  -- Allow Backdated Leave Application,
    [LVRULE_OPHSELF] CHAR(1) NULL  -- Option to follow self declared optional holidays,
