    [LVRULE_CALENDARID] BIGINT NULL  -- Calendar ID,
    [LVRULE_NPHCONVERT] CHAR(1) NULL  -- Convertion of NPH Weekly off to this leave type allowed? Y/N,
    [LVRULE_PRORATE] CHAR(1) NULL  -- Prorate demonomination to be checked for  Broken period,
    [LVRULE_ADDLDAYS] INT NULL  -- Additional Leave entitlement allowed,
    [LVRULE_LEAVECANBETAKEN] CHAR(1) NULL  -- Leave can be taken though balance is available ? Y/N,
    [LVRULE_CHECKESI] CHAR(1) NULL  -- Only Applicable for Non ESI Cases (Y/N),
    [LVRULE_AUTOADDL] CHAR(1) NULL  -- Add Additional Leave Automatically (Y/N),
    [LVRULE_COMPSLAB] CHAR(1) NULL  -- (Y/N),
    [LVRULE_PRORATEDOS] CHAR(1) NULL  -- (Y/N),
