    [LVRULE_PROBATIONCREDITDYS] BIGINT NULL  -- How many days credit to be given if LVRULE_PROBATIONPRORATE is Yes for each frequency,
    [LVRULE_TIMEBASEDAPPLICATION] CHAR(1) NULL  -- Is this leave allowed for time base Yes/No,
    [LVRULE_PROBATIONCREDIMINTDYS] BIGINT NULL,
