    [RULE_OTMINHOURSPERDAY] INT NULL  -- Minimum No of overtime hours allowed per day,
    [RULE_OTMAXHOURSPERDAY] INT NULL  -- Maximum No of overtime hours allowed per day,
    [RULE_COMPOFFALLOWED] CHAR(1) NOT NULL  -- COFF allowed (Y/N),
